#include "../../sdk/application.h"
#include "../../sdk/stream.h"
static struct cb_client client;
__attribute__((noreturn)) static void fail(cb_status_t status){cb_handle_t error=cb_standard(2);const char *message=status==CB_NOT_FOUND?"cat: not found\n":status==CB_DENIED?"cat: permission denied\n":status==CB_READ_ONLY?"cat: read-only filesystem\n":status==CB_BROKEN_PIPE?"cat: broken pipe\n":"cat: I/O failure\n";if(error)(void)cb_write_all(&client,error,message,cb_length(message));cb_exit(status);}

__attribute__((noreturn)) void _start(const struct cb_startup *packet){struct cb_application_start start;CB_REQUIRE(cb_application_start(packet,&start) && start.header.cwd_bytes<4096);char cwd[4096];cb_copy(cwd,start.cwd,start.header.cwd_bytes);cwd[start.header.cwd_bytes]=0;cb_handle_t in=cb_standard(0),out=cb_standard(1),fs=0;if(!out)cb_exit(CB_BAD_HANDLE);uint64_t count=start.header.argc>1?start.header.argc:2;for(uint64_t i=1;i<count;++i){cb_handle_t input=in;if(start.header.argc>1){if(!fs)fs=cb_acquire(CB_FILESYSTEM_NAME,(struct cb_interface_id)CB_FILESYSTEM_INTERFACE_ID);char path[4096];if(!cb_path(path,sizeof(path),cwd,cb_application_argument(&start,i)))cb_exit(CB_BAD_REQUEST);cb_status_t s=cb_fs_call(&client,fs,CB_FILESYSTEM_OPEN,path,CB_FILE_READ,0);if(s)fail(s);cb_copy(&input,cb_result(&client),8);}if(!input)cb_exit(CB_BAD_HANDLE);for(;;){unsigned char buffer[4096];size_t n=0;cb_status_t s=cb_stream_read(&client,input,buffer,sizeof(buffer),&n,0);if(s)fail(s);if(!n)break;s=cb_write_all(&client,out,buffer,n);if(s)fail(s);}if(start.header.argc>1)CB_REQUIRE(cb_system_release(input)==CB_OK);}if(fs)cb_system_release(fs);cb_exit(0);}
